<script setup lang="ts">
import { ref, watch } from "vue";
import { item, request, query, type TrialPolicy, type Plan, type Page } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
const props=defineProps<{modelValue:TrialPolicy;disabled?:boolean}>();const emit=defineEmits<{"update:modelValue":[TrialPolicy]}>();
const selected=ref<Plan|null>(null);const rows=ref<Plan[]>([]);const page=ref(1);const pages=ref(1);const q=ref("");const error=ref("");const state=ref<"idle"|"loading"|"ready"|"error">("idle");let version=0;
function change<K extends keyof TrialPolicy>(key:K,value:TrialPolicy[K]):void{emit("update:modelValue",{...props.modelValue,[key]:value});}
async function load():Promise<void>{const token=++version;state.value="loading";error.value="";try{const result=await request<Page<Plan>>(`/v1/admin/plans?${query({q:q.value,page:page.value,active:true})}`);if(token!==version)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;state.value="ready";}catch(cause){if(token!==version)return;state.value="error";error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}}
watch(()=>props.modelValue.plan_id,async id=>{selected.value=null;if(id===null)return;try{const result=await item<Plan>(`/v1/admin/plans/${id}`);if(props.modelValue.plan_id===id)selected.value=result;}catch(cause){error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}},{immediate:true});
const fields=[{key:"max_claims_per_customer",label:"Claims per account"},{key:"cooldown_seconds",label:"Claim cooldown (seconds)"},{key:"quota_bytes",label:"Trial quota (bytes)"},{key:"duration_days",label:"Duration Experimental (days)"}] as const;
</script>
<template><fieldset :disabled="disabled" class="form-grid"><legend>Trial subscription policy</legend><label class="field"><span>Download Experimental Active</span><input type="checkbox" :checked="modelValue.enabled" @change="change('enabled',($event.target as HTMLInputElement).checked)"/></label><label class="field"><span>Eligibility</span><select aria-label="Eligibility" :value="modelValue.eligibility" @change="change('eligibility',($event.target as HTMLSelectElement).value as TrialPolicy['eligibility'])"><option value="no_paid_purchase">No previous paid purchase</option><option value="any_customer">Any customer with service access</option></select></label><label class="field"><span>Concurrent trial subscriptions</span><select aria-label="Concurrent trial subscriptions" :value="modelValue.concurrent_mode" @change="change('concurrent_mode',($event.target as HTMLSelectElement).value as TrialPolicy['concurrent_mode'])"><option value="reject_active">Reject until current subscription ends</option><option value="allow_multiple">Allow multiple within the claim limit</option></select></label><NumField v-for="field in fields" :key="field.key" :model-value="String(modelValue[field.key])" :label="field.label" @update:model-value="change(field.key,Number($event))"/><p>The source plan price is not charged. Its network policy and delivery group are recorded with the trial quota and duration.</p><p v-if="selected">Source plan: {{ selected.title }} · {{ selected.is_active?'Active':'Inactive' }}</p><p v-else-if="modelValue.plan_id!==null">Plan Selected {{ faNumber(modelValue.plan_id) }}</p><p v-else>No source plan selected.</p><p v-if="error" class="message error" role="alert">{{ error }}</p><div class="toolbar"><label class="field"><span>Find trial source plan</span><input v-model="q" @keydown.enter.prevent="page=1;load()"/></label><button type="button" class="btn secondary" @click="page=1;load()">Find source plan</button><button type="button" class="btn secondary" @click="change('plan_id',null)">Clear source plan</button></div><p v-if="state==='loading'">Loading plans…</p><p v-if="state==='ready'&&!rows.length">No plans found.</p><div class="inline-actions"><button v-for="row in rows" :key="row.id" type="button" class="btn secondary" :aria-pressed="modelValue.plan_id===row.id" @click="selected=row;change('plan_id',row.id)">{{ row.title }}</button></div><div v-if="state==='ready'" class="pager"><button type="button" :disabled="page<=1" @click="page--;load()">‹</button><span>{{ faNumber(page) }} of {{ faNumber(pages) }}</span><button type="button" :disabled="page>=pages" @click="page++;load()">›</button></div></fieldset></template>
